"""Local-only, standard-library static renderer. No scraping or remote generation."""
import json, html, re
from pathlib import Path
from urllib.parse import urlparse
ROOT=Path(__file__).resolve().parents[1]
def esc(s):return html.escape(str(s),quote=True)
def bullets(xs):return '<ul>'+''.join('<li>'+esc(x)+'</li>' for x in xs)+'</ul>'
def validate(r):
 assert len(r['selected'])==len({x['id'] for x in r['selected']}),'duplicate source id'
 for x in r['selected']:
  for k in ['title','author','published_at','verified_at','stage','verified_facts','our_actions','limits','url']:assert x[k],(x['id'],k)
  u=urlparse(x['url']);assert u.scheme=='https' and u.hostname in ('x.com','www.v2ex.com')
 assert '年份待核验' in next(x['published_at'] for x in r['selected'] if x['id']=='v2ex-1203195')
 assert r['updated_at'].endswith('+08:00')
r=json.loads((ROOT/'data/research.json').read_text());validate(r)
if '--validate' in __import__('sys').argv:
 print('Data valid:',len(r['selected']),'cases,',len({x['author'] for x in r['selected']}),'authors');raise SystemExit
cards=[]
for i,x in enumerate(r['selected'],1):
 detail='<h4>原文核验到的陈述</h4>'+bullets(x['verified_facts'])+'<h4>我们的具体动作</h4>'+bullets(x['our_actions'])+'<h4>限制与反例</h4>'+bullets(x['limits'])
 if x.get('date_note'):detail+='<p class="note">日期：'+esc(x['date_note'])+'</p>'
 cards.append(f'''<article class="case" data-author="{esc(x['author'])}" data-stage="{esc(x['stage'])}" data-topic="{esc(x['tags'][0])}"><div class="case-top"><span class="number">{i:02}</span><span class="tag">{esc(x['tags'][0])}</span></div><p class="meta">{esc(x['author'])} <span>· {esc(x['published_at'])}</span></p><h3>{esc(x['title'])}</h3><p>{esc(x['why_read'])}</p><p class="stage">适用阶段 / {esc(x['stage'])}</p><details><summary>事实、动作与适用边界 <span>＋</span></summary><div class="case-body">{detail}</div></details><a class="source" href="{esc(x['url'])}" target="_blank" rel="noopener noreferrer">阅读作者原文 ↗</a><small>{esc(x['evidence_label'])}</small></article>''')
y=r['yetone'];supp=''.join('<li>'+esc(x['fact'])+' <a href="'+esc(x['url'])+'" target="_blank" rel="noopener noreferrer">作者补充 ↗</a></li>' for x in y['author_supplements'])
loops=[('01','接住真实反馈','GitHub × Discord','判断 issue 的价值，复现问题，审查 PR 并验证；把讨论接回交付。','不是“有人提就做”，也不是“审过文字就算验证”。'),('02','先过滤，再深挖','X × 低成本判断','先判断帖子是否与 Magpie 有关，再处理有价值的建议和可复现 bug。','低价筛选也会漏报；我们建议保留抽样复核。'),('03','让错误变成约束','清理 × 经验沉淀','定期检查低质或恶意代码，记录误合并、漏测和维护经验。','复盘要形成可执行检查，不是无限堆积提示词。')]
loophtml=''.join(f'<article class="loop"><span class="number">{n}</span><p class="eyebrow">{sub}</p><h3>{title}</h3><p>{text}</p><p class="note">{note}</p><details><summary>查看原帖截图 <span>↗</span></summary><a href="assets/loop{int(n)}.png" target="_blank" rel="noopener"><img src="assets/loop{int(n)}.png" alt="yetone 第{int(n)}个loop提示词截图，可点击放大" loading="lazy"></a></details></article>' for n,title,sub,text,note in loops)
htmlout='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="精读 yetone 的三循环工作流，连接中文产品构建者的一手经验：真实反馈、可信验证、产品增长与持续交付。"><meta name="theme-color" content="#f6f5ef"><title>从反馈到交付 · 中文产品开发经验</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body><a class="skip" href="#main">跳到正文</a><header><a class="brand" href="#">构建者手记<span> / FIELD NOTES</span></a><nav aria-label="主导航"><a href="#reading">原帖精读</a><a href="#library">经验库</a><a href="#practice">行动清单</a></nav><a class="repo" href="https://github.com/JerichoDing/product-dev-insights" target="_blank" rel="noopener noreferrer">GitHub ↗</a></header><main id="main"><section class="hero"><div><p class="eyebrow"><span class="dot"></span> 中文产品开发经验 / VOL. 01</p><h1>从反馈<span>到交付。</span></h1><p class="lead">AI 能更快写出代码。<br>但值得交付的产品，来自真实问题与可信验证。</p><p class="intro">从 yetone 的三个工作循环出发，连接中文构建者的一手经验。把“看起来很厉害”，拆成你下一次开发能用上的动作。</p><a class="button" href="#reading">开始精读 <span>↓</span></a></div><aside class="hero-diagram" aria-label="从反馈到交付的闭环"><div class="diagram-label">THE PRODUCT LOOP <span>↻</span></div><div class="flow-node"><b>01</b><div>听见问题<small>真实用户，而非想象中的需求</small></div></div><div class="flow-line">↓</div><div class="flow-node"><b>02</b><div>交付证据<small>复现 → 修改 → 验证</small></div></div><div class="flow-line">↓</div><div class="flow-node"><b>03</b><div>沉淀判断<small>把返工变成下一次的约束</small></div></div><p>人在方向和风险处把关，<br>自动化负责可验证的执行。</p></aside></section><div class="stats"><div><strong>03</strong><span>工作循环</span></div><div><strong>09</strong><span>精选原文</span></div><div><strong>07</strong><span>一手作者</span></div><p>不以热度代替质量<br>不把作者自述写成独立审计</p></div><section id="reading"><div class="section-heading"><p class="eyebrow">01 / DEEP READING</p><h2>没有魔法，<br>但有前提。</h2><p>yetone · 2026 年 10 月 13 日 11:56（上海时间）<br><a href="https://x.com/yetone/status/2109855710444237018" target="_blank" rel="noopener noreferrer">阅读原帖 ↗</a></p></div><div class="reading-intro"><blockquote>“我会并行执行图里的 3 个 loop”<cite>— @yetone，原帖节选</cite></blockquote><p>作者说自己用 Claude Code 与官方 Opus 5.5 运行循环，晚上主要处理 UI/UX。但真正值得抄的不是模型名，而是反馈、验证和复盘之间的连接。</p></div><div class="loops">'''+loophtml+'''</div><p class="caption">图解为我们的归纳；展开可查看作者原始截图。图片中的自动回复、合并、发版或拉黑，不代表你已给代理这些权限。</p><div class="two-col"><article class="panel"><p class="eyebrow">作者事实 / FIRST PERSON</p><h3>循环背后的基础设施</h3><ul>'''+supp+'''</ul></article><article class="panel dark"><p class="eyebrow">我们的解读 / EDITORIAL</p><h3>不是无人负责，<br>而是责任重新分配。</h3>'''+bullets(y['our_implications'])+'''</article></div><details class="evidence"><summary>第三方分析，不等于独立验证 <span>＋</span></summary><div><p><a href="https://x.com/wquguru/status/2109650264601117141" target="_blank" rel="noopener noreferrer">@wquguru 的引用文章 ↗</a> 从仓库历史解释了文档路由、错题本、回退测试与发布闸门。这是第三方作者的分析，本研究没有复跑统计。</p>'''+bullets(y['quoted_article']['claims'])+'''<p>'''+esc(y['quoted_article']['warning'])+'''</p><p><a href="https://x.com/junjiechou1122/status/2109850104987562225" target="_blank" rel="noopener noreferrer">社区贡献者澄清 ↗</a>：'''+esc(y['community_correction']['fact'])+'''</p></div></details><details class="evidence"><summary>读到了什么，还有哪些证据缺口？ <span>＋</span></summary><div><p>'''+esc(y['reading_status'])+'''</p>'''+bullets(y['argument']+y['evidence_gaps'])+'''</div></details></section><section id="library"><div class="section-heading"><p class="eyebrow">02 / THE LIBRARY</p><h2>少一点成功学，<br>多一点具体过程。</h2><p>9 篇、7 位作者，覆盖真实工程、产品体验、增长与失败。<br>每篇都保留适用条件，不将个案当定律。</p></div><div class="filters"><label class="search-label">搜索经验<input type="search" id="search" placeholder="试试：付费、测试、Mole…" autocomplete="off"></label><label>主题<select id="topic"><option value="">全部主题</option><option>工程验证</option><option>设计体验</option><option>需求与增长</option></select></label><label>作者<select id="author"><option value="">全部作者</option>'''+''.join('<option>'+esc(a)+'</option>' for a in sorted({x['author'] for x in r['selected']}))+'''</select></label><label>阶段<select id="stage"><option value="">全部阶段</option>'''+''.join('<option>'+esc(a)+'</option>' for a in sorted({x['stage'] for x in r['selected']}))+'''</select></label><button id="reset" type="button">重置</button></div><div class="library-meta"><p id="result-count" role="status" aria-live="polite">显示 9 篇经验</p><button id="export" type="button">保存当前阅读清单 ↓</button></div><p class="note">商业结果仅核验到作者公开作出该陈述，未审计后台。阅读状态保存在当前浏览器，不上传。</p><div id="cases" class="cases">'''+''.join(cards)+'''</div><p id="empty" hidden>没有匹配结果。换个关键词，或重置筛选。</p></section><section id="practice" class="practice"><div class="section-heading"><p class="eyebrow">03 / PUT IT TO WORK</p><h2>下一次开发，<br>先做这些事。</h2><p>我们的执行建议，不是作者原话。<br>点击勾选，进度只保存在本地浏览器。</p></div><ol class="checklist">'''+''.join(f'<li><label><input type="checkbox" data-task="{i}"><span><b>{i+1:02}</b>{esc(t)}</span></label></li>' for i,t in enumerate(y['action_checklist']))+'''</ol><p id="progress" role="status">已完成 0 / 8</p><details class="evidence"><summary>开始自动化前，先设定安全边界 <span>＋</span></summary><div>'''+bullets(y['our_guardrails'])+'''</div></details></section><section id="method"><div class="section-heading"><p class="eyebrow">04 / EVIDENCE & REVISIONS</p><h2>可信，比完整更重要。</h2></div><div class="two-col"><article class="panel"><h3>如何选文</h3><p>优先一手构建者、真实产品、可描述的过程和明确的限制。保留失败样本；不收录只有匿名营收截图、泛泛资源列表的帖子。</p><p>两篇候选因产品实物无法跟踪或作者署名缺失，暂不列入主精选。日期不能确定时，明确标注，不猜年份。</p><p><a href="data/research.json">下载结构化研究数据 ↗</a></p></article><article class="panel"><h3>维护与修订</h3><p>'''+esc(r['changes'][0]['summary'])+'''</p><p class="meta">研究核验：'''+esc(r['researched_at'])+'''<br>本版整理：'''+esc(r['updated_at'])+'''<br>时区：Asia/Shanghai（UTC+8）</p><p>数据由本地维护、校验和构建；本页没有后台爬虫，没有自动收集个人数据。持续更新以实际新增证据为准。</p></article></div></section></main><footer><p>构建者手记 / 从反馈到交付</p><p>原创归纳 · 一手溯源 · 保留不确定性</p><small>版本 '''+esc(r['revision'])+''' · <a href="https://github.com/JerichoDing/product-dev-insights">查看源码与修订历史 ↗</a></small></footer></body></html>'''
# Keep display counts derived from the content source on future updates.
count=len(r['selected']); authors=len({x['author'] for x in r['selected']}); tasks=len(y['action_checklist'])
htmlout=htmlout.replace('<strong>09</strong>',f'<strong>{count:02}</strong>').replace('<strong>07</strong>',f'<strong>{authors:02}</strong>').replace('9 篇、7 位作者',f'{count} 篇、{authors} 位作者').replace('显示 9 篇经验',f'显示 {count} 篇经验').replace('已完成 0 / 8',f'已完成 0 / {tasks}')
(ROOT/'index.html').write_text(htmlout)
print('Built index.html locally')
